script:
class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { q: 'ипотека', type: 'video', topic: 'all', topicOpen: false, stepsOpen: false, onHome: true,
      open: null, ovlTop: 24, watched: { l1: 1, l2: 1, l3: 1, l4: 1 }, newsRead: false, toast: '' };
  }
  say(m) { this.setState({ toast: m }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); }
  renderVals() {
    const S = this.state;
    const NB = ' ';
    const DOK = 'dokumenty.dc.html', PROF = 'profil.dc.html', KOM = 'komanda.dc.html', KLI = 'klienty.dc.html', POM = 'pomoshch.dc.html';
    const TYPES = [['all', 'Все'], ['video', 'Видео'], ['lesson', 'Уроки'], ['guide', 'Гиды PDF'], ['webinar', 'Записи вебинаров']];
    const TYPE_NAME = { video: 'Видео', lesson: 'Урок', guide: 'Гид PDF', webinar: 'Запись вебинара' };
    const TOPICS = ['Кабинет и сервис', 'Как работать с клиентом', 'Страны и рынки', 'Застройщики и проекты', 'Деньги и договор', 'Стандарты работы', 'Что нового'];
    const F = (name, pages) => ({ name, pages });
    const ITEMS = [
      { id: 'l1', type: 'lesson', n: 1, title: 'Как передать первого клиента', topic: 'Как работать с клиентом', dur: '3 мин', next: 'l2', pct: 0,
        desc: 'Что нужно знать о клиенте, чтобы передать его без ошибок: имя, телефон, страна и чего он хочет. Показано на живом примере.', files: [F('Памятка: что нужно для передачи клиента', '1 стр.')] },
      { id: 'l2', type: 'lesson', n: 2, title: 'Что сказать клиенту в первом разговоре', topic: 'Как работать с клиентом', dur: '5 мин', next: 'l3', pct: 0,
        desc: 'Как начать разговор, о чём спросить и чего не обещать. Короткие фразы, которые можно взять себе.', files: [F('Шпаргалка первого разговора', '2 стр.')] },
      { id: 'l3', type: 'lesson', n: 3, title: 'Когда и сколько Вы получаете', topic: 'Деньги и договор', dur: '4 мин', next: 'l4', pct: 0,
        desc: 'Состояния денег простыми словами: будущая выплата, к выплате, выплачено. Когда деньги становятся Вашими.', files: [F('Путь денег по сделке, схема', '1 стр.')] },
      { id: 'l4', type: 'lesson', n: 4, title: 'Как работает Ваша личная ссылка', topic: 'Кабинет и сервис', dur: '3 мин', next: 'l5', pct: 0,
        desc: 'Клиент, который придёт по ссылке, закрепится за Вами. Где взять ссылку, как отправить и что видно после перехода.', files: [F('Как поделиться ссылкой: шаги', '1 стр.')] },
      { id: 'l5', type: 'lesson', n: 5, title: 'Как собрать подборку для клиента', topic: 'Кабинет и сервис', dur: '4 мин', next: 'l6', pct: 0,
        desc: 'Выберите объекты, соберите из них подборку и отправьте клиенту одной ссылкой.', files: [F('Чек-лист подборки', '1 стр.')] },
      { id: 'l6', type: 'lesson', n: 6, title: 'Что делать, если клиент молчит', topic: 'Как работать с клиентом', dur: '5 мин', next: 'a1', pct: 0,
        desc: 'Когда писать повторно, что сказать и когда оставить клиента в покое.', files: [F('Три сообщения, чтобы вернуть клиента в разговор', '2 стр.')] },
      { id: 'v1', type: 'video', title: 'Знакомство с кабинетом', topic: 'Кабинет и сервис', dur: '5 мин', next: 'v2', pct: HB.isNovice() ? 0 : 60,
        desc: 'Обзор разделов: где клиенты, где деньги, где материалы и помощь. Для тех, кто открыл кабинет впервые.', files: [F('Карта кабинета', '1 стр.')] },
      { id: 'v2', type: 'video', title: 'Как говорить с клиентом о рисках', topic: 'Как работать с клиентом', dur: '6 мин', next: 'v3', isNew: true, pct: 0,
        desc: 'Честный разговор о сроках, ценах и возможных задержках. Как не пугать и не обещать лишнего.', files: [F('Как говорить о рисках: примеры фраз', '3 стр.')] },
      { id: 'v3', type: 'video', title: 'ОАЭ: что важно знать клиенту', topic: 'Страны и рынки', dur: '7 мин', next: 'v4', pct: 0,
        desc: 'Как покупают недвижимость в ОАЭ иностранцы: какие бывают объекты, как идёт оплата, какие вопросы задают чаще всего.', files: [F('ОАЭ: коротко для клиента', '4 стр.')] },
      { id: 'v4', type: 'video', title: 'Турция и Кипр: как покупают иностранцы', topic: 'Страны и рынки', dur: '7 мин', next: 'v5', pct: 0,
        desc: 'Две страны рядом: чем они похожи, чем отличаются и каким клиентам что подходит.', files: [F('Турция и Кипр: коротко для клиента', '5 стр.')] },
      { id: 'v5', type: 'video', title: 'Таиланд и Грузия: на что смотреть клиенту', topic: 'Страны и рынки', dur: '8 мин', next: 'w1', isNew: true, pct: 0,
        desc: 'Правила покупки для иностранцев, частые вопросы и что стоит уточнить до передачи клиента.', files: [F('Таиланд и Грузия: коротко для клиента', '5 стр.')] },
      { id: 'g1', type: 'guide', title: 'Стандарты работы', topic: 'Стандарты работы', dur: '8 разделов', sign: true, pct: 0, link: DOK,
        desc: 'Прочтите один раз перед первым клиентом: что можно, что нельзя и как считаются деньги.', files: [] },
      { id: 'g2', type: 'guide', title: 'Как считаются деньги: гид простыми словами', topic: 'Деньги и договор', dur: '6 стр.', pct: 0,
        desc: 'Состояния денег и как считается Ваша доля. Можно сохранить и открыть без интернета.', files: [] },
      { id: 'w1', type: 'webinar', title: 'Как выбрать застройщика и проект', topic: 'Застройщики и проекты', dur: '48 мин', date: '22 октября 2026', next: 'g1', pct: 0,
        desc: 'Запись вебинара от 22 октября 2026. На что смотреть в застройщике, как читать описание проекта и о чём спросить менеджера.', files: [F('Презентация вебинара', '12 стр.')] },
      { id: 'a1', type: 'lesson', title: 'Академия обучения', topic: 'Кабинет и сервис', dur: 'скоро', academy: true, pct: 0,
        desc: 'Академия обучения пока недоступна для этого бренда.', files: [] },
      { id: 'n1', type: 'video', title: 'Наши обновления', topic: 'Что нового', dur: 'раздел', next: 'l4', news: true, pct: 0,
        desc: 'Что мы сделали на платформе за последнее время.', files: [] }
    ];
    const NEWS = [];
    const SECTIONS = ['Кого приводить', 'Как выглядит принятая заявка', 'Готовность клиента и Ваша доля', 'Что происходит после передачи', 'Как считаются деньги', 'Ваша сеть простыми словами', 'Что запрещено', 'За что закрывают доступ'];
    const COURSE = ['l1', 'l2', 'l3', 'l4', 'l5', 'l6'];
    const STARTER = ['l1', 'l2', 'l3', 'l4', 'l5', 'l6'];
    const byId = (id) => ITEMS.find((x) => x.id === id);
    const isW = (id) => !!S.watched[id];
    const nextId = COURSE.find((id) => !isW(id)) || null;
    const topOf = (e) => { try { const b = e.currentTarget.closest('.ob-body'); return Math.max(16, Math.round(e.currentTarget.getBoundingClientRect().top - b.getBoundingClientRect().top) - 40); } catch (x) { return 24; } };
    const openIt = (id) => (e) => this.setState({ open: id, ovlTop: topOf(e) });
    const st = (it) => {
      const w = isW(it.id);
      const newOn = it.isNew && !w && !(it.news && S.newsRead);
      return {  stOk: w, stPct: !w && it.pct > 0, stNext: !w && it.id === nextId, stSign: !w && !!it.sign && it.id !== nextId,
        stNew: !w && it.id !== nextId && !it.sign && it.pct === 0 && !!newOn,
        stIdle: !w && it.type === 'lesson' && it.id !== nextId && !it.sign && it.pct === 0 && !newOn };
    };
    const card = (it) => {
      const s = st(it);
      const pctText = it.pctText || ('просмотрено ' + it.pct + '%');
      const tag = it.type === 'lesson' && it.n ? 'Урок ' + it.n : it.type === 'guide' ? 'PDF' : it.type === 'webinar' ? 'Вебинар' : it.academy ? 'Курс' : '';
      return { id: it.id, title: it.title, topic: it.topic, typeName: TYPE_NAME[it.type], tag, hasTag: tag !== '', dur: it.dur, num: it.n,
        isPlay: it.type === 'video' || it.type === 'lesson', isDoc: it.type === 'guide', isCam: it.type === 'webinar',
        pvCls: it.type === 'guide' ? 'ob-card__p ob-card__p--doc' : 'ob-card__p', hasBar: !isW(it.id) && it.pct > 0, barStyle: '--w:' + it.pct + '%',
        pctText, ...s, isNextCls: s.stNext ? 'ob-st is-next' : 'ob-st',
        aria: it.title + '. ' + TYPE_NAME[it.type] + ', ' + it.topic + '. Открыть', open: openIt(it.id) };
    };
    const q = S.q.trim().toLowerCase();
    const filtering = q !== '' || S.type !== 'all' || S.topic !== 'all';
    const hit = (it) => (S.type === 'all' || it.type === S.type) && (S.topic === 'all' || it.topic === S.topic)
      && (!q || (it.title + ' ' + it.topic + ' ' + TYPE_NAME[it.type] + ' ' + it.desc).toLowerCase().includes(q));
    const grid = (filtering ? ITEMS.filter(hit) : ITEMS.filter((it) => !STARTER.includes(it.id))).map(card);
    const starter = filtering ? [] : STARTER.map((id) => card(byId(id)));
    const courseDone = COURSE.filter(isW).length;
    const topicLabel = S.topic === 'all' ? 'Все темы' : S.topic;
    const topicList = [['all', 'Все темы']].concat(TOPICS.map((t) => [t, t])).map(([v, label]) => ({ label, sel: S.topic === v, cur: S.topic === v ? 'is-cur' : '',
      pick: () => this.setState({ topic: v, topicOpen: false }) }));
    const chips = TYPES.map(([k, label]) => ({ label, pressed: S.type === k, pick: () => this.setState({ type: k }) }));
    const reset = () => this.setState({ q: '', type: 'all', topic: 'all', topicOpen: false });
    const info = filtering ? 'Найдено: ' + grid.length : '';
    // окно просмотра
    const cur = S.open ? byId(S.open) : null;
    const w = cur ? isW(cur.id) : false;
    const nx = cur && cur.next ? byId(cur.next) : null;
    let main = { label: '', href: '', isNext: false, isLink: false, icon: 'arrow' };
    if (cur) {
      if (cur.academy) main = { label: 'Открыть академию', isLink: true, href: '#academy', icon: 'ext' };
      else if (cur.link) main = { label: 'Читать стандарты', isLink: true, href: cur.link, icon: 'arrow' };
      else if (cur.type === 'guide') main = { label: 'Скачать PDF', isDl: true, icon: 'dl' };
      else main = { label: cur.type === 'video' || cur.type === 'webinar' ? 'Следующее видео' : 'Следующий урок', isNext: true, icon: 'arrow' };
    }
    const modal = cur ? { title: cur.title, topic: cur.topic, typeName: TYPE_NAME[cur.type], dur: cur.dur, date: cur.date || '', hasDate: !!cur.date, desc: cur.desc,
      isVideo: cur.type !== 'guide', isDoc: cur.type === 'guide',
      barStyle: '--w:' + (w ? 100 : cur.pct) + '%', timeText: cur.type === 'guide' ? '' : (w ? 'просмотрено' : cur.pct > 0 ? 'просмотрено ' + cur.pct + '%' : '0:00 из ' + cur.dur.replace(' мин', ':00')),
      docText: cur.type === 'guide' ? 'PDF, ' + cur.dur : '',
      files: cur.files, hasFiles: cur.files.length > 0, filesTitle: cur.type === 'guide' ? 'Материалы' : 'Материалы к уроку',
      isStd: !!cur.link, isAcademy: !!cur.academy, isNews: !!cur.news, sections: SECTIONS.map((t, i) => ({ t, href: DOK + '#d-s' + (i + 1) })),
      news: NEWS.map((n) => ({ ...n, fresh: n.fresh && !S.newsRead })),
      newsBtn: S.newsRead ? 'Всё прочитано' : 'Отметить всё прочитанным',
      markLabel: w ? 'Убрать отметку' : (cur.type === 'guide' ? 'Отметить прочитанным' : 'Отметить просмотренным'),
      watched: w, hasNext: main.isNext && !!nx, nextTitle: nx ? 'Дальше: ' + nx.title : '',
      main, mainIsNext: main.isNext, mainIsLink: main.isLink, mainIsDl: !!main.isDl, mainIcoArrow: main.icon === 'arrow', mainIcoExt: main.icon === 'ext', mainIcoDl: main.icon === 'dl',
      stOkBadge: w } : { title: '', files: [], sections: [], news: [], main: {} };
    const steps = [
      { t: 'Аккаунт создан', done: true },
      { t: 'Заполните профиль', done: true },
      { t: 'Подпишите договор', cur: true, href: PROF, act: 'Открыть профиль' },
      { t: 'Откройте Азбуку и пройдите тур по кабинету', done: true },
      { t: 'Пригласите первого коллегу', href: KOM, act: 'Открыть команду' },
      { t: 'Передайте первого клиента', done: true } ].map((s, i) => ({ ...s, num: i + 1, hasAct: !!s.href, cls: s.done ? 'is-done' : s.cur ? 'is-cur' : '', notDone: !s.done, isCur: !!s.cur }));
    return { toastOn: !!S.toast, toast: S.toast, help: () => this.say('Здесь видео, уроки и гиды. Начните с первого урока.'), dl: () => this.say('В кабинете файл скачается на Ваше устройство'), 
      q: S.q, onQ: (e) => this.setState({ q: e.target.value }), chips, topicLabel, topicList, topicOpen: S.topicOpen,
      toggleTopic: () => this.setState({ topicOpen: !S.topicOpen }),
      starter, hasStarter: starter.length > 0, courseDone, courseTotal: COURSE.length, courseBar: 'width:' + Math.round(courseDone / COURSE.length * 1000) / 10 + '%', grid, hasGrid: grid.length > 0, empty: grid.length === 0, filtering, info, reset,
      gridTitle: filtering ? 'Найденные материалы' : 'Все материалы',
      stepsOpen: S.stepsOpen, stepsBtn: S.stepsOpen ? 'Скрыть шаги' : 'Показать все шаги', toggleSteps: () => this.setState({ stepsOpen: !S.stepsOpen }),
      steps, onHome: S.onHome, homeOff: !S.onHome, toggleHome: () => this.setState({ onHome: !S.onHome }),
      openNext: (e) => this.setState({ open: nextId || 'a1', ovlTop: 24 }),
      showModal: !!cur, modal, ovlStyle: 'padding-top: ' + S.ovlTop + 'px',
      closeOvl: (e) => { if (e.target === e.currentTarget) this.setState({ open: null }); },
      closeBtn: () => this.setState({ open: null }),
      toggleWatched: () => this.setState({ watched: { ...S.watched, [cur.id]: w ? 0 : 1 } }),
      goNext: () => this.setState({ open: cur.next, watched: { ...S.watched, [cur.id]: 1 } }),
      readNews: () => this.setState({ newsRead: true }),
      dok: DOK, prof: PROF, kom: KOM, kli: KLI, pom: POM
    };
  }
}
